CREATE OR REPLACE FUNCTION public.bixgo_driver_set_online(p_online boolean) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN UPDATE public.bixgo_driver_licenses SET online=p_online,updated_at=now() WHERE user_id=auth.uid() AND status='approved'; IF NOT FOUND THEN RAISE EXCEPTION 'License is not approved'; END IF; DELETE FROM public.bixgo_dispatch_positions WHERE user_id=auth.uid(); RETURN p_online; END; $$;